import js from '@eslint/js';
import prettier from 'eslint-config-prettier';
import globals from 'globals';
import tseslint from 'typescript-eslint';
import planeahead from './tools/eslint/index.js';

export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/.turbo/**',
      '**/.wrangler/**',
      // Generated by `wrangler types` and committed. 15k lines of runtime declarations with their
      // own eslint-disable directives; linting it reports on Cloudflare's code, not ours.
      'apps/api/worker-configuration.d.ts',
      // apps/mobile is a placeholder until increment 9 creates the Expo app.
      'apps/mobile/**',
      // The typed client's consumer check (increment 8): it imports the declaration `tsc -b`
      // emits into dist/, which lint cannot assume exists; the api `typecheck` script checks it.
      'apps/api/test/consumer/**',
    ],
  },
  js.configs.recommended,
  {
    files: ['**/*.js', '**/*.mjs', '**/*.cjs'],
    languageOptions: {
      ecmaVersion: 'latest',
      sourceType: 'module',
      globals: globals.node,
    },
  },
  {
    files: ['packages/*/**/*.ts', 'apps/api/**/*.ts'],
    extends: [tseslint.configs.recommendedTypeChecked],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
      globals: globals.node,
    },
  },
  {
    // Every file ESLint sees, source and test alike. A raw NUL anywhere makes git treat that blob
    // as binary, and the file loses its diff for good; catching it here is what makes the failure
    // loud, because prettier, tsc and the toolchain guard all accept it silently.
    files: ['**/*.ts', '**/*.tsx', '**/*.js', '**/*.mjs', '**/*.cjs'],
    plugins: { planeahead },
    rules: {
      'planeahead/no-literal-control-characters': 'error',
    },
  },
  {
    files: ['apps/api/src/**/*.ts', 'packages/db/src/**/*.ts'],
    plugins: { planeahead },
    rules: {
      'planeahead/no-module-scope-drizzle': 'error',
    },
  },
  prettier,
);
